using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF 9 writes "$type" instead of "Discriminator".
            // Existing 500K docs have "Discriminator", and direct SQL queries
            // reference c.Discriminator.  Keep the EF 8 name.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product");

            // BREAKING CHANGE 2 — id format changed.
            // EF 8: "Product|123"   EF 9: "123"
            // Existing docs use the old format.  Map a string CosmosId
            // property to the JSON "id" field and generate the EF 8 format.
            entity.Property(p => p.CosmosId)
                  .ToJsonProperty("id")
                  .HasValueGenerator<ProductIdGenerator>();
            entity.HasKey(p => p.CosmosId);

            // BREAKING CHANGE 3 — HasIndex now throws for Cosmos.
            // It was silently ignored in EF 8.  Removed the HasIndex call.
        });
    }
}

class Product
{
    // Cosmos "id" — keeps the EF 8 "Product|<key>" format for existing data.
    public string CosmosId { get; set; } = null!;
    public int ProductId { get; set; }
    public string Sku { get; set; } = null!;
}

/// <summary>Generates id values in the EF 8 format: "Product|{ProductId}".</summary>
class ProductIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var product = (Product)entry.Entity;
        return $"Product|{product.ProductId}";
    }
}

